import{_ as a,o as e,c as n,a3 as s}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"数据架构与状态所有权","description":"区分业务数据库、Agent State、Checkpoint、Store、向量索引与缓存，按所有权、生命周期和恢复方式决定数据位置。","frontmatter":{"title":"数据架构与状态所有权","description":"区分业务数据库、Agent State、Checkpoint、Store、向量索引与缓存，按所有权、生命周期和恢复方式决定数据位置。","framework":"通用 Agent 应用 / LangGraph","version":"Python 3.12 / PostgreSQL 18 / LangGraph 1.x","verified_at":"2026-07-30","source":["https://docs.langchain.com/oss/python/langgraph/persistence","https://docs.langchain.com/oss/python/langgraph/stores","https://www.postgresql.org/docs/current/ddl-constraints.html","https://www.postgresql.org/docs/current/ddl-rowsecurity.html"],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"py-agent/application/data-persistence/data-architecture-state-ownership.md","filePath":"py-agent/application/data-persistence/data-architecture-state-ownership.md","lastUpdated":1785589115000}'),d={name:"py-agent/application/data-persistence/data-architecture-state-ownership.md"};function i(r,t,l,o,p,c){return e(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="数据架构与状态所有权" tabindex="-1">数据架构与状态所有权 <a class="header-anchor" href="#数据架构与状态所有权" aria-label="Permalink to &quot;数据架构与状态所有权&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>一个 Agent 请求可能同时产生用户消息、图状态、检查点、长期记忆、向量、缓存项和后台任务。它们都可以“存进数据库”，但并不因此属于同一种数据。真正决定存放位置的，是谁拥有这条数据、需要保存多久、出现冲突时以谁为准，以及数据丢失后能否重建。</p><p>本章建立数据位置的判断模型，不展开 PostgreSQL 表结构、LangGraph Checkpointer API 或 Redis 命令。后续文章分别讲这些实现；这里先把边界划清，否则实现越完整，重复状态和不一致反而越多。</p><h2 id="_1-数据位置由职责决定" tabindex="-1">1. 数据位置由职责决定 <a class="header-anchor" href="#_1-数据位置由职责决定" aria-label="Permalink to &quot;1. 数据位置由职责决定&quot;">​</a></h2><h3 id="_1-1-先问四个问题" tabindex="-1">1.1 先问四个问题 <a class="header-anchor" href="#_1-1-先问四个问题" aria-label="Permalink to &quot;1.1 先问四个问题&quot;">​</a></h3><p>为一条数据选择存储位置前，依次回答：</p><ol><li><strong>谁是权威所有者</strong>：哪个组件有权创建、修改和删除它？</li><li><strong>生命周期是什么</strong>：只活在一次执行中，还是跨 Thread、跨用户会话长期存在？</li><li><strong>一致性要求是什么</strong>：它是否必须与用户、订单、任务等业务事实原子提交？</li><li><strong>能否重建</strong>：丢失后可以从权威数据重新计算，还是会造成不可恢复的业务损失？</li></ol><p>例如，“任务已取消”会决定 Worker 是否继续产生费用，属于业务事实；“本次图下一步执行 <code>summarize</code> 节点”描述运行位置，属于 Checkpoint；“某段文档的 Embedding”可以从原文重新计算，属于派生索引。</p><h3 id="_1-2-权威数据与派生数据" tabindex="-1">1.2 权威数据与派生数据 <a class="header-anchor" href="#_1-2-权威数据与派生数据" aria-label="Permalink to &quot;1.2 权威数据与派生数据&quot;">​</a></h3><p>权威数据是系统对外承诺的事实，派生数据是为了执行、检索或加速而产生的表示：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>权威数据</span></span>
<span class="line"><span>  tenants / users / threads / runs / messages / tasks</span></span>
<span class="line"><span>       |            |          |</span></span>
<span class="line"><span>       |            |          +--&gt; 缓存、队列投递</span></span>
<span class="line"><span>       |            +-------------&gt; Checkpoint、Trace</span></span>
<span class="line"><span>       +--------------------------&gt; 长期记忆、向量索引</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>箭头表示“可以由前者触发或派生”，不表示派生层可以反过来覆盖业务事实。若缓存说任务仍在运行，而 PostgreSQL 中任务已经取消，应用必须以业务数据库为准。</p><h2 id="_2-六类数据的所有权" tabindex="-1">2. 六类数据的所有权 <a class="header-anchor" href="#_2-六类数据的所有权" aria-label="Permalink to &quot;2. 六类数据的所有权&quot;">​</a></h2><h3 id="_2-1-业务数据库-产品事实" tabindex="-1">2.1 业务数据库：产品事实 <a class="header-anchor" href="#_2-1-业务数据库-产品事实" aria-label="Permalink to &quot;2.1 业务数据库：产品事实&quot;">​</a></h3><p>业务数据库保存应用必须长期解释和约束的数据，例如：</p><ul><li>租户与用户身份映射；</li><li>Thread 的标题、所有者和归档状态；</li><li>一次 Agent Run 的输入摘要、状态、结果和错误；</li><li>用户消息与对外展示的 Agent 消息；</li><li>后台 Task 的状态、幂等键、重试次数和租约；</li><li>授权、审计、计费和外部副作用记录。</li></ul><p>这些数据通常需要外键、唯一约束、事务、权限查询和迁移。即使 Agent 框架被替换，业务数据库仍要能够回答：“哪个用户在什么时候发起了什么任务，当前结果是什么？”</p><p>业务数据库不是所有运行时对象的镜像。模型的每个 Token、每个节点的临时局部值以及可重建向量不应无差别塞入业务表。</p><h3 id="_2-2-agent-state-一次执行的工作集" tabindex="-1">2.2 Agent State：一次执行的工作集 <a class="header-anchor" href="#_2-2-agent-state-一次执行的工作集" aria-label="Permalink to &quot;2.2 Agent State：一次执行的工作集&quot;">​</a></h3><p>State 是模型、工具和节点在一次执行中共同读取和更新的数据，例如当前消息、计划、中间结果和路由标记。它回答的是：</p><blockquote><p>这次执行现在知道什么，下一步计算需要什么？</p></blockquote><p>State 的所有者是 Agent 或 Workflow Runtime。节点返回 State 更新，框架按 Reducer 或字段规则合并。它不是权限来源：<code>tenant_id</code>、<code>user_id</code> 和授权范围应来自受信任的 Runtime Context，不能由模型改写的 State 决定。</p><p>State 可以被 Checkpointer 保存，但“被保存”不等于变成业务事实。状态字段应保持精简，避免放入完整数据库对象、连接、客户端、巨大文件或长期密钥。</p><h3 id="_2-3-checkpoint-执行恢复快照" tabindex="-1">2.3 Checkpoint：执行恢复快照 <a class="header-anchor" href="#_2-3-checkpoint-执行恢复快照" aria-label="Permalink to &quot;2.3 Checkpoint：执行恢复快照&quot;">​</a></h3><p>Checkpoint 保存某个 Thread 在执行边界的 State 快照、下一步节点和运行元数据。它主要服务于：</p><ul><li>多轮状态延续；</li><li>Interrupt 与 Resume；</li><li>故障后从已完成步骤恢复；</li><li>状态历史、调试和时间旅行。</li></ul><p>Checkpoint 的所有者是工作流运行时。应用通过 <code>thread_id</code> 定位执行历史，但不能假设 Checkpoint 中的数据适合业务查询或永久保留。删除过期检查点不应删除用户账户、消息审计或已完成任务；反过来，更新业务表也不会自动修改旧快照。</p><p>应用中的 Thread 记录与 LangGraph <code>thread_id</code> 可以使用同一个 UUID，方便关联，但两者职责不同：前者是产品会话，后者是 Checkpointer 的持久化作用域。</p><h3 id="_2-4-store-跨-thread-的长期记忆" tabindex="-1">2.4 Store：跨 Thread 的长期记忆 <a class="header-anchor" href="#_2-4-store-跨-thread-的长期记忆" aria-label="Permalink to &quot;2.4 Store：跨 Thread 的长期记忆&quot;">​</a></h3><p>Store 保存应用显式选择、需要跨 Thread 读取的数据，例如用户偏好、经过治理的事实或可复用经验。它通常以 <code>namespace + key + value</code> 组织，并由应用或节点显式读写。</p><p>Store 与业务数据库的边界不由“保存时间长短”决定，而由权威性决定：</p><ul><li>用户在设置页明确选择的语言偏好，原始事实应在业务数据库；</li><li>从对话中提取、带置信度和来源的偏好候选，可以进入记忆 Store；</li><li>记忆被确认后，可以通过受控用例同步回业务事实；</li><li>模型不能仅凭一次推断直接改写账户、权限或计费字段。</li></ul><p>长期记忆必须保留来源、版本、有效期和删除能力。Store 不是“把所有聊天记录永久保存”的别名。</p><h3 id="_2-5-向量索引-可检索的派生表示" tabindex="-1">2.5 向量索引：可检索的派生表示 <a class="header-anchor" href="#_2-5-向量索引-可检索的派生表示" aria-label="Permalink to &quot;2.5 向量索引：可检索的派生表示&quot;">​</a></h3><p>向量索引保存 Chunk、Embedding、元数据过滤字段和源记录引用，负责根据距离返回候选。它回答的是：</p><blockquote><p>哪些已索引内容与当前查询最相近？</p></blockquote><p>原始文档、权限和发布状态应有独立的权威来源。向量记录至少要携带 <code>tenant_id</code>、<code>source_id</code>、<code>source_version</code> 和 Chunk ID，使应用能够过滤、追溯和重建。</p><p>Embedding 模型或切分策略变化时，旧索引可能整体失效。正确做法是按版本构建新索引、验证后切换，而不是把向量当作不可替代的原始数据。检索系统返回的元数据也不能替代实时权限检查。</p><h3 id="_2-6-缓存-带失效条件的副本" tabindex="-1">2.6 缓存：带失效条件的副本 <a class="header-anchor" href="#_2-6-缓存-带失效条件的副本" aria-label="Permalink to &quot;2.6 缓存：带失效条件的副本&quot;">​</a></h3><p>缓存保存可重新获取或计算的数据副本，例如：</p><ul><li>Thread 列表的短期查询结果；</li><li>模型供应商元数据；</li><li>已验证且输入完全相同的确定性结果；</li><li>限流计数和短期协调状态。</li></ul><p>每个缓存项都需要回答“何时失效”。常见依据包括 TTL、源记录版本、事件驱动删除和 Namespace 版本。若无法描述失效条件，就还没有设计好缓存。</p><p>缓存丢失只能影响性能，不能让业务事实丢失。Redis 是否开启持久化，也不会自动把缓存升级为业务数据库。</p><h2 id="_3-贯穿应用的身份模型" tabindex="-1">3. 贯穿应用的身份模型 <a class="header-anchor" href="#_3-贯穿应用的身份模型" aria-label="Permalink to &quot;3. 贯穿应用的身份模型&quot;">​</a></h2><h3 id="_3-1-tenant-id-与-user-id" tabindex="-1">3.1 <code>tenant_id</code> 与 <code>user_id</code> <a class="header-anchor" href="#_3-1-tenant-id-与-user-id" aria-label="Permalink to &quot;3.1 \`tenant_id\` 与 \`user_id\`&quot;">​</a></h3><p><code>tenant_id</code> 是最强的数据隔离边界，<code>user_id</code> 是租户内的主体。它们由认证与授权层解析，并通过受信任上下文传入数据访问层：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>access token</span></span>
<span class="line"><span>  -&gt; Authentication</span></span>
<span class="line"><span>  -&gt; RequestContext(tenant_id, user_id, scopes)</span></span>
<span class="line"><span>  -&gt; repository query WHERE tenant_id = :tenant_id</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>不能从请求正文、Prompt 或模型输出直接接受任意 <code>tenant_id</code>。数据库查询必须显式带租户条件；对高风险系统，还可以用复合外键和 PostgreSQL Row-Level Security 做纵深防御。</p><h3 id="_3-2-thread-id" tabindex="-1">3.2 <code>thread_id</code> <a class="header-anchor" href="#_3-2-thread-id" aria-label="Permalink to &quot;3.2 \`thread_id\`&quot;">​</a></h3><p><code>thread_id</code> 表示一个可持续的产品会话。它关联用户可见消息和多次 Run，也可以作为 Checkpointer 的 Thread 键：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Thread(thread_id)</span></span>
<span class="line"><span>  ├─ Message 1</span></span>
<span class="line"><span>  ├─ Run A -&gt; Checkpoint A0, A1, A2</span></span>
<span class="line"><span>  ├─ Message 2</span></span>
<span class="line"><span>  └─ Run B -&gt; Checkpoint B0, B1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>复用 ID 只是关联策略，不会自动完成授权。读取 Checkpoint 前仍应先查询业务 Thread，确认当前租户和用户有访问权。</p><h3 id="_3-3-run-id" tabindex="-1">3.3 <code>run_id</code> <a class="header-anchor" href="#_3-3-run-id" aria-label="Permalink to &quot;3.3 \`run_id\`&quot;">​</a></h3><p><code>run_id</code> 表示一次有业务意义的 Agent 执行。它用于关联输入、结果、错误、Trace、成本和本次产生的消息。一个 Thread 可以有多次 Run；一次恢复是否沿用原 <code>run_id</code>，应由产品语义决定并保持稳定。</p><p>不要默认把框架内部 Trace ID、模型请求 ID 或某个节点 ID 当作业务 <code>run_id</code>。它们可以作为关联字段保存，但生命周期和稳定性不同。</p><h3 id="_3-4-task-id" tabindex="-1">3.4 <code>task_id</code> <a class="header-anchor" href="#_3-4-task-id" aria-label="Permalink to &quot;3.4 \`task_id\`&quot;">​</a></h3><p><code>task_id</code> 表示后台执行单元。API 可以先创建 Run，再创建一个或多个 Task 交给 Worker。Task 负责排队、租约、重试和死信；Run 负责用户看到的整体执行状态：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Run(run_id, status=&quot;running&quot;)</span></span>
<span class="line"><span>  ├─ Task(task_id=A, type=&quot;retrieve&quot;, status=&quot;succeeded&quot;)</span></span>
<span class="line"><span>  └─ Task(task_id=B, type=&quot;generate&quot;, status=&quot;running&quot;)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>同一个 Task 的重试不应生成新的业务动作身份，否则幂等和审计会失效。若需要逐次审计，可增加 <code>task_attempts</code>，而不是把每次尝试伪装成新 Task。</p><h2 id="_4-同一信息应该写到哪里" tabindex="-1">4. 同一信息应该写到哪里 <a class="header-anchor" href="#_4-同一信息应该写到哪里" aria-label="Permalink to &quot;4. 同一信息应该写到哪里&quot;">​</a></h2><h3 id="_4-1-数据位置决策表" tabindex="-1">4.1 数据位置决策表 <a class="header-anchor" href="#_4-1-数据位置决策表" aria-label="Permalink to &quot;4.1 数据位置决策表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>信息</th><th>权威位置</th><th>可选派生位置</th><th>原因</th></tr></thead><tbody><tr><td>用户所属租户</td><td>业务数据库/身份系统</td><td>请求上下文缓存</td><td>权限事实，必须可约束</td></tr><tr><td>Thread 标题与归档状态</td><td>业务数据库</td><td>列表缓存</td><td>产品实体，需要查询和更新</td></tr><tr><td>当前图的下一节点</td><td>Checkpoint</td><td>Trace</td><td>执行恢复信息</td></tr><tr><td>本次工具中间结果</td><td>State/Checkpoint</td><td>Trace</td><td>只服务当前执行</td></tr><tr><td>已确认语言偏好</td><td>业务数据库</td><td>Store、缓存</td><td>明确用户设置是业务事实</td></tr><tr><td>对话推断的偏好</td><td>Store</td><td>语义索引</td><td>带来源和置信度的记忆</td></tr><tr><td>文档原文与权限</td><td>文档源/业务数据库/对象存储</td><td>向量索引</td><td>原文是权威数据</td></tr><tr><td>Chunk Embedding</td><td>向量索引</td><td>本地查询缓存</td><td>可由原文和模型版本重建</td></tr><tr><td>Task 是否取消</td><td>业务数据库</td><td>Redis/队列通知</td><td>Worker 必须以持久事实复核</td></tr><tr><td>模型响应缓存</td><td>缓存</td><td>无</td><td>只为减少重复计算</td></tr></tbody></table><h3 id="_4-2-不要让两处都能独立修改" tabindex="-1">4.2 不要让两处都能独立修改 <a class="header-anchor" href="#_4-2-不要让两处都能独立修改" aria-label="Permalink to &quot;4.2 不要让两处都能独立修改&quot;">​</a></h3><p>如果业务表和 Store 都能独立修改“用户语言偏好”，系统就没有唯一答案。应明确写入方向：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>设置页 -&gt; 业务数据库（权威） -&gt; 事件/同步 -&gt; Store 与缓存</span></span>
<span class="line"><span>对话推断 -&gt; Store（候选） -&gt; 用户确认 -&gt; 业务数据库</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>同步失败时，派生层可以重试或重建；权威层不能被旧副本回写覆盖。每条同步链应携带源版本或事件 ID，以拒绝乱序更新。</p><h2 id="_5-一次请求的数据流" tabindex="-1">5. 一次请求的数据流 <a class="header-anchor" href="#_5-一次请求的数据流" aria-label="Permalink to &quot;5. 一次请求的数据流&quot;">​</a></h2><h3 id="_5-1-从-api-到持久结果" tabindex="-1">5.1 从 API 到持久结果 <a class="header-anchor" href="#_5-1-从-api-到持久结果" aria-label="Permalink to &quot;5.1 从 API 到持久结果&quot;">​</a></h3><p>下面是一条典型链路：</p><ol><li>API 从认证结果取得 <code>tenant_id</code> 和 <code>user_id</code>。</li><li>PostgreSQL 验证 Thread 归属，并创建 <code>run_id</code> 与 <code>task_id</code>。</li><li>Worker 领取 Task，加载业务输入和受信任 Runtime Context。</li><li>Agent Runtime 创建 State；Checkpointer 按 <code>thread_id</code> 保存执行快照。</li><li>RAG 用业务权限过滤向量索引，返回带 <code>source_id</code> 的候选。</li><li>Agent 可以显式读取 Store 中的长期记忆，但不能据此提升权限。</li><li>执行完成后，事务更新 Run、Task，并追加用户可见 Message。</li><li>缓存失效事件在提交后发布；Trace 保存各步骤的观测数据。</li></ol><p>这条链路中没有一笔跨 PostgreSQL、Checkpointer、向量库和 Redis 的全局事务。应用通过权威记录、幂等操作、Outbox 和可恢复同步处理跨系统一致性。</p><h3 id="_5-2-失败时以什么恢复" tabindex="-1">5.2 失败时以什么恢复 <a class="header-anchor" href="#_5-2-失败时以什么恢复" aria-label="Permalink to &quot;5.2 失败时以什么恢复&quot;">​</a></h3><table tabindex="0"><thead><tr><th>失败位置</th><th>恢复依据</th></tr></thead><tbody><tr><td>API 在提交前崩溃</td><td>PostgreSQL 事务回滚；相同幂等键可重试</td></tr><tr><td>Worker 处理中崩溃</td><td>Task 租约到期后重新领取；先检查持久状态</td></tr><tr><td>图节点崩溃</td><td>Checkpoint 从已完成执行边界恢复</td></tr><tr><td>Redis 丢失</td><td>从 PostgreSQL 或上游重新填充缓存</td></tr><tr><td>向量索引损坏</td><td>从原文、Chunk 规则和 Embedding 版本重建</td></tr><tr><td>Store 同步失败</td><td>按源事件 ID 重试，不覆盖更新版本</td></tr></tbody></table><p>Checkpoint 恢复计算，不会自动撤销已经提交到外部系统的邮件、支付或工单。具有副作用的节点仍需幂等键、状态检查或补偿动作。</p><h2 id="_6-生命周期、权限与删除" tabindex="-1">6. 生命周期、权限与删除 <a class="header-anchor" href="#_6-生命周期、权限与删除" aria-label="Permalink to &quot;6. 生命周期、权限与删除&quot;">​</a></h2><h3 id="_6-1-生命周期不能一刀切" tabindex="-1">6.1 生命周期不能一刀切 <a class="header-anchor" href="#_6-1-生命周期不能一刀切" aria-label="Permalink to &quot;6.1 生命周期不能一刀切&quot;">​</a></h3><p>不同数据需要不同保留策略：</p><ul><li>业务审计可能依法保留数月或数年；</li><li>Checkpoint 可在 Run 完成一段时间后压缩或删除；</li><li>Trace 可以采样并脱敏；</li><li>缓存按秒或分钟过期；</li><li>向量索引按源版本重建并淘汰；</li><li>长期记忆需要过期、冲突解决和用户删除入口。</li></ul><p>把所有数据都绑定到“删除 Thread”级联删除，可能同时破坏审计、恢复和合规要求。删除策略应按数据类别设计，并记录执行结果。</p><h3 id="_6-2-权限必须贯穿每个存储" tabindex="-1">6.2 权限必须贯穿每个存储 <a class="header-anchor" href="#_6-2-权限必须贯穿每个存储" aria-label="Permalink to &quot;6.2 权限必须贯穿每个存储&quot;">​</a></h3><p>仅在 HTTP 路由检查权限还不够。后台任务、Checkpointer 查询、Store Namespace 和向量过滤都必须保留租户边界：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP authorization</span></span>
<span class="line"><span>    + repository tenant predicate</span></span>
<span class="line"><span>    + composite foreign key / optional RLS</span></span>
<span class="line"><span>    + Store namespace begins with tenant_id</span></span>
<span class="line"><span>    + vector metadata tenant filter</span></span>
<span class="line"><span>    + cache key includes tenant namespace</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>任何一层缺少租户维度，都可能在重试、后台执行或缓存命中时绕过最初的路由检查。</p><h2 id="_7-常见错误与判断清单" tabindex="-1">7. 常见错误与判断清单 <a class="header-anchor" href="#_7-常见错误与判断清单" aria-label="Permalink to &quot;7. 常见错误与判断清单&quot;">​</a></h2><h3 id="_7-1-常见错误" tabindex="-1">7.1 常见错误 <a class="header-anchor" href="#_7-1-常见错误" aria-label="Permalink to &quot;7.1 常见错误&quot;">​</a></h3><ul><li><strong>把 Checkpoint 当聊天业务表</strong>：方便恢复，却难以做稳定分页、审计和产品级删除。</li><li><strong>把 State 当权限上下文</strong>：模型或节点更新可能改变安全边界。</li><li><strong>把 Store 当用户主档</strong>：推断记忆会覆盖明确设置，且缺少业务事务。</li><li><strong>把向量库当原文仓库</strong>：模型和切分升级后无法可靠重建。</li><li><strong>把 Redis 当最终任务状态</strong>：缓存丢失或过期会让任务凭空消失。</li><li><strong>复制数据却不记录版本</strong>：旧缓存、旧记忆或旧索引可能覆盖新事实。</li><li><strong>复用 <code>thread_id</code> 就默认已授权</strong>：标识关联不等于访问控制。</li></ul><h3 id="_7-2-设计检查清单" tabindex="-1">7.2 设计检查清单 <a class="header-anchor" href="#_7-2-设计检查清单" aria-label="Permalink to &quot;7.2 设计检查清单&quot;">​</a></h3><p>为每类数据填写以下问题，缺一项就不应进入实现：</p><table tabindex="0"><thead><tr><th>问题</th><th>示例答案</th></tr></thead><tbody><tr><td>权威所有者是谁？</td><td><code>runs</code> 表由应用用例更新</td></tr><tr><td>主键和租户边界是什么？</td><td><code>tenant_id + run_id</code></td></tr><tr><td>谁可以写、谁可以读？</td><td>用户发起，Worker 更新，租户成员读取</td></tr><tr><td>生命周期多长？</td><td>业务 Run 保留一年，Checkpoint 保留 30 天</td></tr><tr><td>是否需要事务约束？</td><td>Run 与 Task 创建必须同事务</td></tr><tr><td>是否可重建？</td><td>Embedding 可重建，用户消息不可丢失</td></tr><tr><td>冲突时以谁为准？</td><td>PostgreSQL 业务状态优先于缓存</td></tr><tr><td>删除如何传播？</td><td>先删权威记录，再异步清理索引和缓存</td></tr><tr><td>如何关联观测数据？</td><td><code>tenant_id/thread_id/run_id/task_id</code></td></tr></tbody></table><p>数据架构的目标不是让每种存储都保存一份完整状态，而是让每份数据只有一个清楚的所有者，其余副本都能解释来源、版本和失效方式。</p>`,91)])])}const b=a(d,[["render",i]]);export{u as __pageData,b as default};
